#!/usr/bin/env bash

# Compiles the Wren modules the Wren converter generated by importing every one of them with wren_cli. Wren imports are
# relative paths so the hand written runtime, the Wren sources of the dependencies (META-INF/wren/src of their jars),
# and this project are copied to one tree first. This project's sources are written to <output>/src.
# Arguments: source_dir output_dir object_dir dependency_dir runtime_dir compiler "flags" artifactId fail_on_error

set -uo pipefail

export PATH="/usr/local/bin:/usr/bin:/bin:$PATH"

source_dir="$(cygpath -u "$1")"
output_dir="$(cygpath -u "$2")"
object_dir="$(cygpath -u "$3")"
dependency_dir="$(cygpath -u "$4")"
runtime_dir="$(cygpath -u "$5")"
compiler="$(cygpath -u "$6")"
read -r -a compiler_flags <<< "$7"
artifact="$8"
fail_on_error="${9:-true}"

if [ ! -d "$source_dir" ]; then
    echo "No Wren sources: $source_dir"
    exit 0
fi

rm -rf "$output_dir" "$object_dir"
tree="$object_dir/tree"
mkdir -p "$output_dir/src" "$tree"
cp -R "$source_dir/." "$output_dir/src/"
cp -R "$runtime_dir/." "$tree/"
if [ -d "$dependency_dir/src" ]; then
    cp -R "$dependency_dir/src/." "$tree/"
fi
cp -R "$source_dir/." "$tree/"

# Wren CLI can not open a path over the Windows 260 character limit, which a deep project folder plus a deep package
# reaches, so the check runs in a short temporary copy of the tree
short_tree="$(mktemp -d /tmp/wrenXXXXXX)"
trap 'rm -rf "$short_tree"' EXIT
cp -R "$tree/." "$short_tree/"
cd "$short_tree" || exit 1
check="jcheck_$artifact.wren"
count=0
# Each module is imported in its own fiber so every module is checked. A module of a dependency's optional dependency
# (not transitive like Java, such as TsUtil) can be missing: only that is allowed.
modules="$object_dir/modules.txt"
echo "var jerror = null" > "$check"
while IFS= read -r file; do
    module="${file#"$source_dir"/}"
    echo "./${module%.wren}" >> "$modules"
    # A one line block is an expression so the import statement needs its own line
    printf 'jerror = Fiber.new {\n  import "./%s"\n}.try()\n' "${module%.wren}" >> "$check"
    echo "if (jerror != null) System.print(\"jcheck error: %(jerror)\")" >> "$check"
    count=$((count + 1))
done < <(find "$source_dir" -type f -name '*.wren' | sort)
echo "System.print(\"Wren compiled: $artifact\")" >> "$check"
echo "Wren modules: $count"

output="$("$compiler" "${compiler_flags[@]}" "$check" 2>&1)"
status=$?
echo "$output"
# Problems: compile errors, and run errors except a missing module that is not one of this project's modules
problems="$(echo "$output" | grep -E 'Error at|Could not compile|jcheck error:' | while IFS= read -r line; do
    missing="$(echo "$line" | sed -n "s/.*Could not load module '\([^']*\)'.*/\1/p")"
    if [ -n "$missing" ] && ! grep -qxF "$missing" "$modules"; then continue; fi
    echo "$line"
done)"
if [ "$status" = "0" ] && [ -z "$problems" ]; then
    exit 0
fi
echo "$problems"
echo "Wren build failed: $artifact" >&2
if [ "$fail_on_error" = "true" ]; then
    exit 1
fi
exit 0
